/**
 * card-fade-slide-up — GSAP animation
 * Generated by the animate pipeline. Edit freely.
 *
 * Duration: 1.2s  FPS: 30
 * NOTE: Spring easing is approximated with GSAP back/elastic eases.
 *       For true spring physics use React Spring or Motion instead.
 *
 * Expected HTML structure:
 * <div class="animation-root">
    <div class="card"></div>
 * </div>
 */

import { gsap } from 'gsap';

/**
 * @param {Element} container — the .animation-root element
 * @returns {gsap.core.Timeline}
 */
export function createCardFadeSlideUp(container) {
  const tl = gsap.timeline({ paused: true });

  tl.from('.card', { y: 120, duration: 1.2, ease: 'back.out(1.7)' }, 0);
  tl.from('.card', { opacity: 0, duration: 0.5, ease: 'power2.out' }, 0);

  return tl;
}

// Autoplay when imported as a demo
if (typeof document !== 'undefined') {
  document.addEventListener('DOMContentLoaded', () => {
    const root = document.querySelector('.animation-root');
    if (root) createCardFadeSlideUp(root).play();
  });
}
